UPDATE orders
SET status = #{status}, pay_time = #{payTime}, pay_method = #{payMethod}
WHERE id = #{id}

UPDATE orders
SET status = #{status}, ship_time = #{shipTime},
    ship_method = #{shipMethod}, tracking_no = #{trackingNo}
WHERE id = #{id}

UPDATE orders
SET status = #{status}, confirm_time = #{confirmTime}
WHERE id = #{id}

mapper.select:
SELECT id, order_no AS orderNo, user_id AS userId, total_amount AS totalAmount, original_amount AS originalAmount, status, address_id AS addressId, receiver_name AS receiverName, receiver_phone AS receiverPhone, province, city, detail_address AS detailAddress, note, pay_method AS payMethod, pay_time AS payTime, ship_time AS shipTime, confirm_time AS confirmTime, ship_method AS shipMethod, tracking_no AS trackingNo, create_time AS createTime FROM orders WHERE 1 = 1 AND status = #{status}
AND (order_no LIKE CONCAT("%", #{keyword}, "%") OR receiver_phone LIKE CONCAT("%", #{keyword}, "%") OR receiver_name LIKE CONCAT("%", #{keyword}, "%"))
ORDER BY create_time DESC LIMIT #{offset}, #{limit}
